solution.solution.cpp:
#include <array>
#include <cstdint>
#include <functional>
#include <string>

using NTSTATUS = std::int32_t;
constexpr NTSTATUS STATUS_SUCCESS = 0, STATUS_PENDING = 0x103;
constexpr NTSTATUS STATUS_INVALID_DEVICE_REQUEST = static_cast<NTSTATUS>(0xC0000010u);
enum Major { IRP_MJ_CREATE = 0, IRP_MJ_CLOSE = 2, IRP_MJ_READ = 3, IRP_MJ_WRITE = 4, IRP_MJ_DEVICE_CONTROL = 14, IRP_MJ_MAXIMUM = 28 };

struct Irp { int major; NTSTATUS status{ 0 }; std::uint64_t information{ 0 }; int completions{ 0 }; bool markedPending{ false }; };

void completeIrp(Irp& irp, NTSTATUS status, std::uint64_t information)
{
    irp.status = status;
    irp.information = information;
    ++irp.completions;
}

void markPending(Irp& irp) { irp.markedPending = true; }

using Dispatch = std::function<NTSTATUS(Irp&)>;

class IoManager
{
public:
    void setDispatch(int major, Dispatch d)
    {
        if (major >= 0 && major < IRP_MJ_MAXIMUM) m_table[static_cast<std::size_t>(major)] = std::move(d);
    }

    std::string send(Irp& irp)
    {
        NTSTATUS returned;
        if (irp.major < 0 || irp.major >= IRP_MJ_MAXIMUM || !m_table[static_cast<std::size_t>(irp.major)])
        {
            completeIrp(irp, STATUS_INVALID_DEVICE_REQUEST, 0);
            returned = STATUS_INVALID_DEVICE_REQUEST;
        }
        else returned = m_table[static_cast<std::size_t>(irp.major)](irp);

        if (irp.completions > 1) return "completed twice";
        if (returned == STATUS_PENDING)
        {
            if (!irp.markedPending) return "pending without mark";
            if (irp.completions == 1) return "pending but completed";
            return "pending";
        }
        if (irp.completions == 0) return "not completed";
        if (returned != irp.status) return "status mismatch";
        return "ok";
    }

private:
    std::array<Dispatch, IRP_MJ_MAXIMUM> m_table{};
};

unitTests:
TEST("a well-behaved driver") {
    IoManager io; io.setDispatch(IRP_MJ_CREATE, [](Irp& i) { completeIrp(i, STATUS_SUCCESS, 0); return STATUS_SUCCESS; });
    io.setDispatch(IRP_MJ_WRITE, [](Irp& i) { completeIrp(i, STATUS_SUCCESS, 42); return STATUS_SUCCESS; });
    Irp a{ IRP_MJ_CREATE }; CHECK_EQ(io.send(a), std::string("ok")); Irp w{ IRP_MJ_WRITE }; CHECK_EQ(io.send(w), std::string("ok")); CHECK_EQ(w.information, 42ull);
}
TEST("no dispatch routine") { IoManager io; Irp r{ IRP_MJ_READ }; CHECK_EQ(io.send(r), std::string("ok")); CHECK_EQ(r.status, STATUS_INVALID_DEVICE_REQUEST); Irp bad{ 99 }; CHECK_EQ(io.send(bad), std::string("ok")); CHECK_EQ(bad.completions, 1); }
TEST("the classic mistakes") {
    IoManager io;
    io.setDispatch(IRP_MJ_READ, [](Irp&) { return STATUS_SUCCESS; });
    io.setDispatch(IRP_MJ_WRITE, [](Irp& i) { completeIrp(i, STATUS_SUCCESS, 0); completeIrp(i, STATUS_SUCCESS, 0); return STATUS_SUCCESS; });
    io.setDispatch(IRP_MJ_CLOSE, [](Irp& i) { completeIrp(i, STATUS_INVALID_DEVICE_REQUEST, 0); return STATUS_SUCCESS; });
    Irp r{ IRP_MJ_READ }, w{ IRP_MJ_WRITE }, c{ IRP_MJ_CLOSE };
    CHECK_EQ(io.send(r), std::string("not completed")); CHECK_EQ(io.send(w), std::string("completed twice")); CHECK_EQ(io.send(c), std::string("status mismatch"));
}
TEST("pending") {
    IoManager io;
    io.setDispatch(IRP_MJ_READ, [](Irp& i) { markPending(i); return STATUS_PENDING; });
    io.setDispatch(IRP_MJ_WRITE, [](Irp&) { return STATUS_PENDING; });
    io.setDispatch(IRP_MJ_DEVICE_CONTROL, [](Irp& i) { markPending(i); completeIrp(i, STATUS_SUCCESS, 0); return STATUS_PENDING; });
    Irp r{ IRP_MJ_READ }, w{ IRP_MJ_WRITE }, d{ IRP_MJ_DEVICE_CONTROL };
    CHECK_EQ(io.send(r), std::string("pending")); CHECK_EQ(io.send(w), std::string("pending without mark")); CHECK_EQ(io.send(d), std::string("pending but completed"));
    completeIrp(r, STATUS_SUCCESS, 7); CHECK_EQ(r.completions, 1);
}

